void SoundTest(void){
	while(1){
		wr8(REG_VOL_SOUND,0xFF);
		wr16(REG_SOUND, (0x6C<< 8) | 0x41);
		wr8(REG_PLAY, 1);
		while(rd8(REG_PLAY)){
			;
		}
	}
}

void VladTest(void){
	uint32 index;
	uint32 unghi = 0;
	//float x, y;

	uint32 j=0;
	//scriere imagine in memorie
	for(uint32 i=0; i< 16384; i+=4, j+=4){
		wr32(RAM_G + j, (((uint32)GUTA[i]) << 0) | (((uint32)GUTA[i+1]) << 8) | (((uint32)GUTA[i+2]) << 16) | (((uint32)GUTA[i+3]) << 24));
	}

	uint32 x = 0 ,y = 0;
	uint8 dirX = 1, dirY = 1; //x: 1 = dreapta, 0 = stanga; y: 1 = jos, 0 = sus
	while(1){
		index = 0;
		if(unghi == 0){
			unghi = 1;
		}
		else if(unghi >= 360){
			unghi = 1;
		}
		//x = cos(unghi * 0.0175);
		//y = sin(unghi * 0.0175);

		if(dirX){
			x++;
		}
		else{
			x--;
		}
		if(dirY){
			y++;
		}
		else{
			y--;
		}
		//verifica margini
		if(x <= 0){
			dirX = 1;
		}
		else if(x >= 800-128){
			dirX = 0;
		}
		if(y <= 0){
			dirY = 1;
		}
		else if(y >= 480-128){
			dirY = 0;
		}

		if(rd8(REG_DLSWAP) == 0){
			wr32(RAM_DL + (index+=4), clear(1, 1, 1)); // clear screen

			/*
			wr32(RAM_DL + (index+=4), color_rgb(223, 171, 124)); // change colour to red
			wr32(RAM_DL + (index+=4), point_size(2200)); // set point size to 20 pixels in radius
			wr32(RAM_DL + (index+=4), begin(POINTS)); // start drawing points
			wr32(RAM_DL + (index+=4), vertex2ii(192, 133, 0, 0)); // red point
			wr32(RAM_DL + (index+=4), end_d());

			wr32(RAM_DL + (index+=4), color_rgb(59, 177, 101));
			wr32(RAM_DL + (index+=4), begin(BITMAPS)); // start drawing bitmaps
			wr32(RAM_DL + (index+=4), vertex2ii(30, 110, 31, 'L'));
			wr32(RAM_DL + (index+=4), vertex2ii(60, 110, 31, 'A'));
			wr32(RAM_DL + (index+=4), vertex2ii(90, 110, 31, 'D'));
			wr32(RAM_DL + (index+=4), vertex2ii(150, 110, 31, 'N'));
			wr32(RAM_DL + (index+=4), vertex2ii(180, 110, 31, 'U'));
			wr32(RAM_DL + (index+=4), vertex2ii(240, 110, 31, 'V'));
			wr32(RAM_DL + (index+=4), vertex2ii(270, 110, 31, 'E'));
			wr32(RAM_DL + (index+=4), vertex2ii(300, 110, 31, 'D'));
			wr32(RAM_DL + (index+=4), vertex2ii(330, 110, 31, 'E'));
			wr32(RAM_DL + (index+=4), vertex2ii(150, 160, 31, 'A'));
			wr32(RAM_DL + (index+=4), vertex2ii(180, 160, 31, 'S'));
			wr32(RAM_DL + (index+=4), vertex2ii(210, 160, 31, 'T'));
			wr32(RAM_DL + (index+=4), vertex2ii(240, 160, 31, 'A'));
			wr32(RAM_DL + (index+=4), vertex2ii(0, 110, 31, 'V'));
			wr32(RAM_DL + (index+=4), end_d());*/

			//wr32(RAM_DL + (index+=4), color_rgb(223, 171, 124));
			/*wr32(RAM_DL + (index+=4), bitmap_source(RAM_G));
			wr32(RAM_DL + (index+=4), bitmap_layout(PALETTED8, 128, 32) );
			wr32(RAM_DL + (index+=4), bitmap_size(0, 0, 0, 32, 32) );
			wr32(RAM_DL + (index+=4), begin(BITMAPS));
			wr32(RAM_DL + (index+=4), vertex2ii(5,0,0,0));
			wr32(RAM_DL + (index+=4), end_d());*/

			wr32(RAM_DL + (index+=4), vertex_translate_x(x*16));
			wr32(RAM_DL + (index+=4), vertex_translate_y(y*16));
			wr32(RAM_DL + (index+=4), bitmap_source(RAM_G));
			wr32(RAM_DL + (index+=4), bitmap_layout(RGB332, 128, 128) );
			wr32(RAM_DL + (index+=4), bitmap_size(0, 0, 0, 128, 128) );
			wr32(RAM_DL + (index+=4), begin(BITMAPS));
			wr32(RAM_DL + (index+=4), vertex2ii(0,0,0,0));
			wr32(RAM_DL + (index+=4), end_d());

			wr32(RAM_DL + (index+=4), display()); // display the image
			wr8(REG_DLSWAP,DLSWAP_FRAME);//display list swap
		}
		unghi++;
		volatile int delay = 80000;
		while(delay--);
	}

}

